===== apps/backend/src/app.ts =====
import cors from 'cors';
import express from 'express';
import helmet from 'helmet';
import pinoHttp from 'pino-http';
import { createSupabaseTokenVerifier, type VerifyAccessToken } from './auth/supabase-auth';
import { loadEnvironment, type Environment } from './config/env';
import { errorHandler } from './middleware/error-handler';
import { notFoundHandler } from './middleware/not-found';
import { createAuthRouter } from './routes/auth.routes';
import { healthRouter } from './routes/health.routes';

export interface AppDependencies {
  environment?: Environment;
  verifyAccessToken?: VerifyAccessToken;
}

export function createApp(dependencies: AppDependencies = {}) {
  const environment = dependencies.environment ?? loadEnvironment();
  const verifyAccessToken =
    dependencies.verifyAccessToken ?? createSupabaseTokenVerifier(environment);

  const allowedOrigins = environment.CORS_ORIGINS.split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);

  const app = express();

  app.disable('x-powered-by');
  app.use(helmet());
  app.use(
    cors({
      origin: allowedOrigins,
      credentials: true,
    }),
  );
  app.use(express.json({ limit: '1mb' }));
  app.use(
    pinoHttp({
      redact: ['req.headers.authorization'],
    }),
  );

  app.use('/api/v1/health', healthRouter);
  app.use('/api/v1/auth', createAuthRouter(verifyAccessToken));

  app.use(notFoundHandler);
  app.use(errorHandler);

  return app;
}
===== apps/backend/src/routes/health.routes.ts =====
import { Router } from 'express';

export const healthRouter = Router();

healthRouter.get('/', (_request, response) => {
  response.status(200).json({
    status: 'ok',
    service: 'sport-analytics-api',
    timestamp: new Date().toISOString(),
  });
});
===== apps/backend/src/routes/auth.routes.ts =====
import { Router } from 'express';
import type { VerifiedIdentity, VerifyAccessToken } from '../auth/supabase-auth';
import { requireAuthentication } from '../middleware/require-authentication';

export function createAuthRouter(verifyAccessToken: VerifyAccessToken): Router {
  const authRouter = Router();

  authRouter.get('/me', requireAuthentication(verifyAccessToken), (_request, response, next) => {
    const identity = response.locals.authenticatedIdentity as VerifiedIdentity | undefined;

    if (!identity) {
      next(new Error('Authenticated identity was not attached to the response'));
      return;
    }

    response.status(200).json({
      identity: {
        subject: identity.uid,
      },
    });
  });

  return authRouter;
}
