:root,
:root[data-theme='day'] {
  --colour-canvas: #f5f2e9;
  --colour-surface: #fffdf7;
  --colour-surface-raised: #eee9dc;
  --colour-text: #102026;
  --colour-text-secondary: #52636a;
  --colour-text-muted: #627078;
  --colour-border: #d9d3c4;
  --colour-primary: #5d7e00;
  --colour-primary-soft: #dff0a7;
  --colour-brand: #e95a24;
  --colour-data-accent: #007f9e;
  --colour-label: #486200;
  --colour-brand-text: #a83b13;
  --colour-focus: #007f9e;
  --shadow-header: 0 8px 28px rgb(16 32 38 / 8%);
  --font-display: 'Arial Narrow', 'Roboto Condensed', Arial, sans-serif;
  --font-interface: 'Segoe UI', Arial, sans-serif;
  color: var(--colour-text);
  background: var(--colour-canvas);
  font-family: var(--font-interface);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

:root[data-theme='night'] {
  --colour-canvas: #08121b;
  --colour-surface: #101e2b;
  --colour-surface-raised: #162736;
  --colour-text: #f6f8f2;
  --colour-text-secondary: #b8c3cc;
  --colour-text-muted: #8ea0af;
  --colour-border: #263847;
  --colour-primary: #c7ff4a;
  --colour-primary-soft: #263b21;
  --colour-brand: #ff6b35;
  --colour-data-accent: #20d5ff;
  --colour-label: #c7ff4a;
  --colour-brand-text: #ff8a5e;
  --colour-focus: #c7ff4a;
  --shadow-header: 0 8px 28px rgb(0 0 0 / 24%);
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  background: var(--colour-canvas);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
  background: var(--colour-canvas);
  color: var(--colour-text);
}

button,
input {
  font: inherit;
}

a {
  color: var(--colour-data-accent);
}

a:focus-visible,
button:focus-visible,
input:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.public-shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.skip-link {
  position: fixed;
  left: 1rem;
  top: -5rem;
  z-index: 100;
  padding: 0.75rem 1rem;
  border: 2px solid var(--colour-focus);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
  font-weight: 600;
  text-decoration: none;
}

.skip-link:focus {
  top: 1rem;
}

.site-header {
  position: relative;
  z-index: 10;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-surface);
  box-shadow: var(--shadow-header);
}

.site-header__inner,
.site-footer__inner,
.content-boundary {
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
}

.site-header__inner {
  min-height: 5.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.brand-link {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  border-radius: 6px;
}

.brand-wordmark {
  display: block;
  width: 11rem;
  max-width: 100%;
}

.brand-wordmark__image {
  display: block;
  width: 100%;
  height: auto;
}

.brand-asset--night {
  display: none;
}

:root[data-theme='night'] .brand-asset--day {
  display: none;
}

:root[data-theme='night'] .brand-asset--night {
  display: block;
}

.theme-control {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--colour-text-secondary);
}

.theme-control__label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

.theme-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.625rem;
  cursor: pointer;
}

.theme-toggle input {
  position: absolute;
  width: 2.75rem;
  height: 1.5rem;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.theme-toggle__track {
  width: 2.75rem;
  height: 1.5rem;
  flex: 0 0 auto;
  padding: 0.1875rem;
  border: 1px solid var(--colour-border);
  border-radius: 999px;
  background: var(--colour-surface-raised);
}

.theme-toggle__thumb {
  display: block;
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: var(--colour-primary);
  transform: translateX(0);
  transition: transform 160ms ease;
}

.theme-toggle input:checked + .theme-toggle__track .theme-toggle__thumb {
  transform: translateX(1.25rem);
}

.theme-toggle input:focus-visible + .theme-toggle__track {
  outline: 3px solid var(--colour-focus);
  outline-offset: 4px;
}

.theme-control__value {
  min-width: 5.75rem;
  color: var(--colour-text);
  font-size: 0.875rem;
  font-weight: 600;
}

main {
  flex: 1;
}

.hero {
  position: relative;
  min-height: min(39rem, calc(100svh - 7.5rem));
  overflow: hidden;
  display: flex;
  align-items: center;
  border-bottom: 1px solid var(--colour-border);
  background: var(--colour-canvas);
}

.hero::before,
.hero::after {
  content: '';
  position: absolute;
  pointer-events: none;
}

.hero::before {
  inset: 2rem 0 2rem 50%;
  border-left: 1px solid var(--colour-border);
}

.hero::after {
  right: 3rem;
  bottom: 2rem;
  width: 7rem;
  border-bottom: 0.5rem solid var(--colour-brand);
}

.hero__content {
  position: relative;
  z-index: 2;
  width: min(100% - 3rem, 100rem);
  margin-inline: auto;
  padding-block: 4rem;
}

.eyebrow {
  margin: 0 0 1rem;
  color: var(--colour-label);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  overflow-wrap: anywhere;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  letter-spacing: 0;
}

h1 {
  margin: 0;
  font-size: 4.5rem;
  line-height: 1;
  text-wrap: balance;
  white-space: nowrap;
}

.hero__tagline {
  max-width: 30rem;
  margin: 1.5rem 0 0;
  color: var(--colour-brand);
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.15;
}

.hero__summary {
  max-width: 35rem;
  margin: 1.5rem 0 0;
  color: var(--colour-text-secondary);
  font-size: 1.125rem;
  line-height: 1.6;
}

