            <RecordFacts>
              <RecordFact label="Season ID" value={season.seasonId} />
              <RecordFact
                label="Competition"
                value={
                  <Link to={`/competitions/${encodeURIComponent(season.competitionId)}`}>
                    {season.competitionId}
