export interface HealthResponse {
  status: 'ok';
  service: string;
  timestamp: string;
}

const apiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? 'http://localhost:3000/api/v1';

export type ApiErrorKind = 'unauthenticated' | 'forbidden' | 'request-failed';

export class ApiResponseError extends Error {
  readonly kind: ApiErrorKind;
  readonly status: number;

  constructor(status: number, message = `API request failed with status ${status}`) {
    const kind =
      status === 401 ? 'unauthenticated' : status === 403 ? 'forbidden' : 'request-failed';

    super(message);
    this.name = 'ApiResponseError';
    this.kind = kind;
    this.status = status;
  }
}

export type AccessTokenProvider = () => string | null;

export interface AuthenticatedApiClient {
  request<ResponseBody>(path: string, init?: RequestInit): Promise<ResponseBody>;
}

export function createAuthenticatedApiClient(
  getAccessToken: AccessTokenProvider,
): AuthenticatedApiClient {
  return {
    async request<ResponseBody>(path: string, init: RequestInit = {}): Promise<ResponseBody> {
      const headers = new Headers(init.headers);
      const accessToken = getAccessToken();

      if (!headers.has('Accept')) {
        headers.set('Accept', 'application/json');
      }

      if (accessToken) {
        headers.set('Authorization', `Bearer ${accessToken}`);
      } else {
        headers.delete('Authorization');
      }

      const normalizedPath = path.startsWith('/') ? path : `/${path}`;
      const response = await fetch(`${apiBaseUrl}${normalizedPath}`, {
        ...init,
        headers,
      });

      if (!response.ok) {
        throw new ApiResponseError(response.status);
      }

      if (response.status === 204) {
        return undefined as ResponseBody;
      }

      return (await response.json()) as ResponseBody;
    },
  };
}

export async function getHealth(signal?: AbortSignal): Promise<HealthResponse> {
  const response = await fetch(`${apiBaseUrl}/health`, {
    headers: {
      Accept: 'application/json',
    },
    signal: signal ?? null,
  });

  if (!response.ok) {
    throw new Error(`Health request failed with status ${response.status}`);
  }

  return (await response.json()) as HealthResponse;
}

import { afterEach, describe, expect, it, vi } from 'vitest';
import { ApiResponseError, createAuthenticatedApiClient } from './client';

function response(status: number, body: unknown = {}): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

describe('authenticated API client', () => {
  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it('attaches the current session access token as a bearer credential', async () => {
    const fetchMock = vi.fn().mockResolvedValue(response(200, { identity: { subject: 'user-1' } }));
    vi.stubGlobal('fetch', fetchMock);
    const client = createAuthenticatedApiClient(() => 'current-access-token');

    await client.request('/auth/me');

    const requestInit = fetchMock.mock.calls[0]?.[1] as RequestInit;
    expect(new Headers(requestInit.headers).get('Authorization')).toBe(
      'Bearer current-access-token',
    );
  });

  it('does not send an authorization header without a session token', async () => {
    const fetchMock = vi.fn().mockResolvedValue(response(200));
    vi.stubGlobal('fetch', fetchMock);
    const client = createAuthenticatedApiClient(() => null);

    await client.request('/auth/me', {
      headers: { Authorization: 'Bearer stale-token' },
    });

    const requestInit = fetchMock.mock.calls[0]?.[1] as RequestInit;
    expect(new Headers(requestInit.headers).has('Authorization')).toBe(false);
  });

  it.each([
    [401, 'unauthenticated'],
    [403, 'forbidden'],
  ] as const)('preserves a %i response as %s', async (status, kind) => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(response(status)));
    const client = createAuthenticatedApiClient(() => 'current-access-token');

    const request = client.request('/auth/me');

    await expect(request).rejects.toBeInstanceOf(ApiResponseError);
    await expect(request).rejects.toMatchObject({ kind, status });
  });
});

